#!/usr/bin/env python3
"""
Round 181b (culprits), 5 October 2026. Needs round 180b.

Glass house replaces Aqua.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 181b (5 October)\n\nNeeds round 180b (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- Owner on 180b's Aqua: \"it just looks baby blue\"; wants modern, sleek\n  ecology, like the house and plants in Ex Machina. Aqua is replaced by\n  Glass house (kind \"glass\", layers \"outline-glass-...\"), same place on the\n  menu. Nothing of Aqua is left.\n- Same method (woodComposite, then glassPaintPixels in two Web Workers):\n  what grows on muted forest greens from spruce shadow to soft moss; bare\n  ground on concrete and stone greys; water dark slate glass; snow cool\n  white. Crisp, not soft: a little local contrast (GLASS.crisp). No glow.\n- Over it: dark graphite sea by depth, soft overcast light, a thin grey mist\n  on mountainsides (700 to 3,200 m), dark lakes, fine pale concrete roads,\n  concrete buildings from zoom 13, faint pale borders, overcast grey sky.\n- Names: THEMED_NAMES.glass, Jost Light and spaced Regular capitals in pale\n  concrete on a dark halo. Layer colours default to \"bright\" (dark ground).\n- Test: every painted colour is muted (no bright green, no orange or\n  yellow). Greens are the earthy ones allowed on basemaps, as on Woodlands.\n  Not seen against the real imagery (EOX blocked here).\n"]

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round181b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 180b" not in h.read_text(encoding="utf-8"):
        sys.exit("round181b: round 180b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round181b: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round181b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round181b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
